sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float brightness;
uniform float contrast;
uniform float highlights;
layout(color) uniform half4 color;
uniform float opacity;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float3 base = c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(0.0);
    half4 g = blurred.eval(coord);
    float3 soft = g.a > 0.0 ? float3(g.rgb) / float(g.a) : float3(0.0);
    float l = clamp(((luma(soft) - 0.5) * (1.0 + contrast) + 0.5) * brightness, 0.0, 1.0);
    float w = mix(1.0, smoothstep(0.25, 1.0, l), clamp((highlights - 0.5) * 2.0, 0.0, 1.0));
    float3 s = float3(l) * w * float3(color.rgb) * clamp(opacity, 0.0, 1.0);
    float3 rgb = base + s - base * s;
    float a = max(float(c.a), float(g.a) * clamp(opacity, 0.0, 1.0));
    return half4(half3(clamp(rgb, 0.0, 1.0)) * half(a), half(a));
}
